-- RelentlessLovePursues admin back end. Paste this whole file into Supabase > SQL Editor > Run.
-- Run it AFTER you have created the admin user (Authentication > Users > Add user).

create table if not exists public.admins (
  id uuid primary key references auth.users(id) on delete cascade
);

create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.admins where id = auth.uid());
$$;

create table if not exists public.posts (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  title text not null,
  category text not null default '',
  excerpt text not null default '',
  body text not null default '',
  cover_url text not null default '',
  published boolean not null default true,
  published_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.episodes (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text not null default '',
  image_url text not null default '',
  youtube text not null default '',
  spotify text not null default '',
  apple text not null default '',
  published boolean not null default true,
  published_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create or replace function public.touch_updated_at() returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;
drop trigger if exists posts_touch on public.posts;
create trigger posts_touch before update on public.posts for each row execute function public.touch_updated_at();
drop trigger if exists episodes_touch on public.episodes;
create trigger episodes_touch before update on public.episodes for each row execute function public.touch_updated_at();

alter table public.admins   enable row level security;
alter table public.posts    enable row level security;
alter table public.episodes enable row level security;

drop policy if exists "admins read self" on public.admins;
create policy "admins read self" on public.admins for select to authenticated using (id = auth.uid());

drop policy if exists "public read posts" on public.posts;
create policy "public read posts" on public.posts for select using (published or public.is_admin());
drop policy if exists "admin write posts" on public.posts;
create policy "admin write posts" on public.posts for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists "public read episodes" on public.episodes;
create policy "public read episodes" on public.episodes for select using (published or public.is_admin());
drop policy if exists "admin write episodes" on public.episodes;
create policy "admin write episodes" on public.episodes for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- Picture / media storage
insert into storage.buckets (id, name, public) values ('media', 'media', true) on conflict (id) do nothing;
drop policy if exists "public read media" on storage.objects;
create policy "public read media" on storage.objects for select using (bucket_id = 'media');
drop policy if exists "admin add media" on storage.objects;
create policy "admin add media" on storage.objects for insert to authenticated with check (bucket_id = 'media' and public.is_admin());
drop policy if exists "admin change media" on storage.objects;
create policy "admin change media" on storage.objects for update to authenticated using (bucket_id = 'media' and public.is_admin());
drop policy if exists "admin delete media" on storage.objects;
create policy "admin delete media" on storage.objects for delete to authenticated using (bucket_id = 'media' and public.is_admin());

-- Everyone who exists right now (the admin user you created) becomes an admin.
insert into public.admins (id) select id from auth.users on conflict do nothing;

-- Move the current 13 blog posts into the new system
insert into public.posts (slug,title,category,excerpt,body,published_at) values ($q$balance-in-your-life$q$, $q$Top tips for creating balance in your life$q$, $q$NATURE · TRENDING$q$, $q$Then, with the maul, after repeatedly smiting the upper end of this iron rod, he placed the blunted needle endwise on the top of it.$q$, $q$<p>A moderate incline runs towards the foot of Maybury Hill, and down this we clattered. Once the lightning had begun, it went on in as rapid a succession of flashes as I have ever seen.</p>
<p>At first I regarded little but the road before me, and then abruptly my attention was arrested by something that was moving rapidly down the opposite slope of Maybury Hill. At first I took it for the wet roof of a house, but one flash following another showed it to be in swift rolling movement.</p>
<p>With a blow from the top-maul Ahab knocked off the steel head of the lance, and then, handing to the mate the long iron rod remaining, bade him hold it upright, without its touching the deck. Then, with the maul, after repeatedly smiting the upper end of this iron rod, he placed the blunted needle endwise on the top of it, and less strongly hammered that, several times, the mate still holding the rod as before.</p>
<p>Owing to a confident reliance upon other means of determining the vessel’s place, some merchantmen, and many whalemen, especially when cruising, wholly neglect to heave the log — though at the same time, and frequently more for form’s sake than anything else, regularly putting down upon the customary slate the course steered by the ship, as well as the presumed average rate of progression every hour. The wooden reel and angular log attached hung, long untouched, just beneath the railing of the after bulwarks.</p>
<p>Then, going through some small strange motions with it — whether indispensable to the magnetizing of the steel, or merely intended to augment the awe of the crew, is uncertain — he called for linen thread, and moving to the binnacle, slipped out the two reversed needles there, and horizontally suspended the sail-needle by its middle, over one of the compass-cards.</p>
<p>For my own part, I had been feverishly excited all day. Something very like the war fever that occasionally runs through a civilised community had got into my blood, and in my heart I was not so very sorry that I had to return that night. I can best express my state of mind by saying that I wanted to be in at the death.</p>
<p>At first, the steel went round and round, quivering and vibrating at either end, but at last it settled to its place. Ahab, who had been intently watching for this result, stepped frankly back from the binnacle, and pointing his stretched arm towards it, exclaimed: “Look ye, for yourselves, if Ahab be not lord of the level loadstone! The sun is East, and that compass swears it!”</p>
<p>One after another they peered in, for nothing but their own eyes could persuade such ignorance as theirs, and one after another they slunk away. In his fiery eyes of scorn and triumph, you then saw Ahab in all his fatal pride.</p>
<p>My wife was curiously silent throughout the drive, and seemed oppressed with forebodings of evil. I talked to her reassuringly, but she answered only in monosyllables. Would that I had stayed. Her face, I remember, was very white as we parted.</p>
<p>Close on its apparition, and blindingly violet by contrast, danced out the first lightning of the gathering storm, and the thunder burst like a rocket overhead. The horse took the bit between his teeth and bolted.</p>$q$, '2026-07-28 09:00:00+00') on conflict (slug) do nothing;
insert into public.posts (slug,title,category,excerpt,body,published_at) values ($q$useful-languages-to-learn$q$, $q$The most useful languages to learn in 2026 and beyond$q$, $q$ECONOMICS · LIFESTYLE$q$, $q$I perceived that in a moment everyone upon this side of the hill would be moving. I found him in his bar, quite unaware of what was going on behind his house.$q$, $q$<p>After many similar hair-breadth escapes, we at last swiftly glided into what had just been one of the outer circles, but now crossed by random whales, all violently making for one centre. This lucky salvation was cheaply purchased by the loss of Queequeg’s hat, who, while standing in the bows to prick the fugitive whales, had his hat taken clean from his head by the air-eddy made by the sudden tossing of a pair of broad flukes close by.</p>
<p>The nearer moon, hurtling suddenly above the horizon and lighting up the Barsoomian scene, showed me that my preserver was Woola, but from whence he had come, or how found me, I was at a loss to know. That I was glad of his companionship it is needless to say, but my pleasure at seeing him was tempered by anxiety as to the reason of his leaving Dejah Thoris.</p>
<p>By the light of the now brilliant moons I saw that he was but a shadow of his former self, and as he turned from my caress and commenced greedily to devour the dead carcass at my feet I realized that the poor fellow was more than half starved. I, myself, was in but little better plight, but I could not bring myself to eat the uncooked flesh, having no means of making a fire.</p>
<p>At daybreak of the fifteenth day of my search, when the amphitheater had cleared, I crept stealthily to the top, and as the great excavation lay far from the plaza and in an untenanted portion of the great dead city, I had little trouble in reaching the hills beyond.</p>
<p>For two days I waited there for Kantos Kan, but as he did not come I started off on foot in a northwesterly direction toward a point where he had told me lay the nearest waterway. My only food consisted of vegetable milk from the plants which gave so bounteously of this priceless fluid.</p>
<p>Several times I was attacked by wild beasts — strange, uncouth monstrosities that leaped upon me in the dark, so that I had ever to grasp my long-sword in my hand that I might be ready for them. Usually my strange, newly acquired telepathic power warned me in ample time, but once I was down, with vicious fangs at my jugular and a hairy face pressed close to mine before I knew that I was even threatened.</p>
<p>What manner of thing was upon me I did not know, but that it was large and heavy and many-legged I could feel. My hands were at its throat before the fangs had a chance to bury themselves in my neck, and slowly I forced the hairy face from me and closed my fingers, vise-like, upon its windpipe.</p>
<p>Without sound we lay there, the beast exerting every effort to reach me with those awful fangs, and I straining to maintain my grip and choke the life from it as I kept it from my throat. Slowly my arms gave to the unequal struggle, and inch by inch the burning eyes and gleaming tusks of my antagonist crept toward me, until, as the hairy face touched mine again, I realized that all was over. And then a living mass of destruction sprang from the surrounding darkness full upon the creature that held me pinioned to the ground. The two rolled growling upon the moss, tearing and rending one another in a frightful manner, but it was soon over, and my preserver stood with lowered head above the throat of the dead thing which would have killed me.</p>$q$, '2026-07-27 09:00:00+00') on conflict (slug) do nothing;
insert into public.posts (slug,title,category,excerpt,body,published_at) values ($q$mediterranean-diet-benefits$q$, $q$5 health benefits of the medi-terranean diet$q$, $q$ENTERTAINMENT · LIFESTYLE$q$, $q$One after another they peered in, for nothing but their own eyes could persuade such ignorance as theirs.$q$, $q$<p>Then going through some small strange motions with it — whether indispensable to the magnetizing of the steel, or merely intended to augment the awe of the crew, is uncertain — he called for linen thread, and moving to the binnacle, slipped out the two reversed needles there, and horizontally suspended the sail-needle by its middle, over one of the compass-cards.</p>
<p>A moderate incline runs towards the foot of Maybury Hill, and down this we clattered. Once the lightning had begun, it went on in as rapid a succession of flashes as I have ever seen. At first I regarded little but the road before me, and then abruptly my attention was arrested by something that was moving rapidly down the opposite slope of Maybury Hill.</p>
<p>For my own part, I had been feverishly excited all day. Something very like the war fever that occasionally runs through a civilized community had got into my blood, and in my heart I was not so very sorry that I had to return that night. I can best express my state of mind by saying that I wanted to be in at the death.</p>
<p>With a blow from the top-maul Ahab knocked off the steel head of the lance, and then, handing to the mate the long iron rod remaining, bade him hold it upright, without its touching the deck. Then, with the maul, after repeatedly smiting the upper end of this iron rod, he placed the blunted needle endwise on the top of it, and less strongly hammered that, several times, the mate still holding the rod as before.</p>
<p>At first, the steel went round and round, quivering and vibrating at either end; but at last it settled to its place, when Ahab, who had been intently watching for this result, stepped frankly back from the binnacle, and pointing his stretched arm towards it, exclaimed: “Look ye, for yourselves, if Ahab be not lord of the level loadstone! The sun is East, and that compass swears it!”</p>
<p>One after another they peered in, for nothing but their own eyes could persuade such ignorance as theirs, and one after another they slunk away. In his fiery eyes of scorn and triumph, you then saw Ahab in all his fatal pride.</p>
<p>While now the fated Pequod had been so long afloat this voyage, the log and line had but very seldom been in use. Owing to a confident reliance upon other means of determining the vessel’s place, some merchantmen, and many whalemen, especially when cruising, wholly neglect to heave the log.</p>
<p>My wife was curiously silent throughout the drive, and seemed oppressed with forebodings of evil. I talked to her reassuringly, but she answered only in monosyllables. Would that I had stayed that night. Her face, I remember, was very white as we parted.</p>
<p>Close on its apparition, and blindingly violet by contrast, danced out the first lightning of the gathering storm, and the thunder burst like a rocket overhead. The horse took the bit between his teeth and bolted.</p>$q$, '2026-07-26 09:00:00+00') on conflict (slug) do nothing;
insert into public.posts (slug,title,category,excerpt,body,published_at) values ($q$slow-practices-that-bring-clarity$q$, $q$3 simple, slow practices that bring clarity$q$, $q$LIFESTYLE · NATURE$q$, $q$I can compare it to nothing but a large door mat, ornamented at the edges with little tinkling tags.$q$, $q$<p>“There,” said the landlord, placing the candle on a crazy old sea chest that did double duty as a wash-stand and centre table, “there, make yourself comfortable now, and good night to ye.” I turned round from eyeing the bed, but he had disappeared.</p>
<p>“Come along here, I’ll give ye a glim in a jiffy,” and so saying he lighted a candle and held it towards me, offering to lead the way. But I stood irresolute; when, looking at a clock in the corner, he exclaimed —</p>
<p>But what is this on the chest? I took it up, and held it close to the light, and felt it, and smelt it, and tried every way possible to arrive at some satisfactory conclusion concerning it. I can compare it to nothing but a large door mat, ornamented at the edges with little tinkling tags, something like the stained porcupine quills round an Indian moccasin. There was a hole or slit in the middle of this mat, as you see the same in South American ponchos. But could it be possible that any sober harpooneer would get into a door mat, and parade the streets of any Christian town in that sort of guise?</p>
<p>Folding back the counterpane, I stooped over the bed. Though none of the most elegant, it yet stood the scrutiny tolerably well. I then glanced round the room; and besides the bedstead and centre table, could see no other furniture belonging to the place, but a rude shelf, the four walls, and a papered fireboard representing a man striking a whale.</p>
<p>Of things not properly belonging to the room, there was a hammock lashed up, and thrown upon the floor in one corner; also a large seaman’s bag, containing the harpooneer’s wardrobe, no doubt in lieu of a land trunk. I sat down on the side of the bed, and commenced thinking about this head-peddling harpooneer, and his door mat.</p>
<p>Whether that mattress was stuffed with corn-cobs or broken crockery, there is no telling, but I rolled about a good deal, and could not sleep for a long time. At last I slid off into a light doze, and had pretty nearly made a good offing towards the land of Nod, when I heard a heavy footfall in the passage, and saw a glimmer of light come into the room from under the door.</p>
<p>Lord save me, thinks I, that must be the harpooneer, the infernal head-peddler. But I lay perfectly still, and resolved not to say a word till spoken to. Holding a light in one hand, and that identical New Zealand head in the other, the stranger entered the room.</p>$q$, '2026-07-25 09:00:00+00') on conflict (slug) do nothing;
insert into public.posts (slug,title,category,excerpt,body,published_at) values ($q$guilt-of-feeling-happy$q$, $q$The guilt of feeling happy and mantras to find your joy$q$, $q$LIFESTYLE · NATURE$q$, $q$I shouted above the sudden noise. She looked away from me downhill. Then I fetched out the servant.$q$, $q$<p>I believe I have broken a finger here against his cursed jaw. Ain’t those mincing knives down in the forecastle there, men? Look to those handspikes, my hearties. Captain, by God, look to yourself — say the word, don’t be a fool; forget it all; we are ready to turn to, treat us decently, and we’re your men; but we won’t be flogged.</p>
<p>I and my wife stood amazed. Then I realised that the crest of the hill must be within range now that the college was cleared out of the way. At that I gripped my wife’s arm, and without ceremony ran her out into the road. Then I fetched out the servant, telling her I would go upstairs myself for the box she was clamouring for.</p>
<p>“We can’t possibly stay here,” I said; and as I spoke the firing reopened for a moment upon the common. “But where are we to go?” said my wife in terror. I thought, perplexed. Then I remembered her cousins at Leatherhead. “Leatherhead!” I shouted above the sudden noise. She looked away from me downhill. The people were coming out of their houses, astonished. “How are we to get to Leatherhead?” she said. “Stop here — you are safe here,” said a voice, but we pressed on regardless.</p>
<p>I started off at once for the Spotted Dog, for I knew the landlord had a horse and dog cart. I ran, for I perceived that in a moment everyone upon this side of the hill would be moving. I found him in his bar, quite unaware of what was going on behind his house. A man stood with his back to me, talking to him.</p>
<p>Down the hill I saw a bevy of hussars ride under the railway bridge; three galloped through the open gates of the Oriental College; two others dismounted, and began running from house to house. The sun, shining through the smoke that drove up from the tops of the trees, seemed blood red, and threw an unfamiliar, lurid light upon everything.</p>$q$, '2026-07-24 09:00:00+00') on conflict (slug) do nothing;
insert into public.posts (slug,title,category,excerpt,body,published_at) values ($q$what-makes-life-easier$q$, $q$What things make your life easier?$q$, $q$FEATURED · TRENDING$q$, $q$I and my wife stood amazed. Then I realised that the crest of Maybury Hill must be within range of the Martians.$q$, $q$<p>“A likely story indeed!” said the Pigeon in a tone of the deepest contempt. “I’ve seen a good many little girls in my time, but never one with such a neck as that! No, no! You’re a serpent, and there’s no use denying it. I suppose you’ll be telling me next that you never tasted an egg!” “I have tasted eggs, certainly,” said Alice, who was a very truthful child, “but little girls eat eggs quite as much as serpents do, you know.” “I don’t believe it,” said the Pigeon, “but if they do, why then they’re a kind of serpent, that’s all I can say.”</p>
<p>This was such a new idea to Alice that she was quite silent for a minute or two, which gave the Pigeon the opportunity of adding, “You’re looking for eggs, I know that well enough, and what does it matter to me whether you’re a little girl or a serpent?” “It matters a good deal to me,” said Alice hastily, “but I’m not looking for eggs, as it happens; and if I was, I shouldn’t want yours: I don’t like them raw.”</p>
<p>“Well, be off, then!” said the Pigeon in a sulky tone, as it settled down again into its nest. Alice crouched down among the trees as well as she could, for her neck kept getting entangled among the branches, and every now and then she had to stop and untwist it. After a while she remembered that she still held the pieces of mushroom in her hands, and she set to work very carefully, nibbling first at one and then at the other, and growing sometimes taller and sometimes shorter, until she had succeeded in bringing herself down to her usual height.</p>
<p>It was so long since she had been anything near the right size that it felt quite strange at first, but she got used to it in a few minutes and began talking to herself, as usual. “Come, there’s half my plan done now! How puzzling all these changes are! I’m never sure what I’m going to be, from one minute to another!” As she said this, she came suddenly upon an open place, with a little house in it about four feet high. “Whoever lives there,” thought Alice, “it’ll never do to come upon them this size: why, I should frighten them out of their wits!” So she began nibbling at the right-hand bit again, and did not venture to go near the house till she had brought herself down to nine inches high.</p>
<p>For a minute or two she stood looking at the house, wondering what to do next, when suddenly a footman in livery came running out of the wood — she considered him to be a footman because he was in livery, otherwise, judging by his face only, she would have called him a fish — and rapped loudly at the door with his knuckles. It was opened by another footman in livery, with a round face and large eyes like a frog; and both footmen, Alice noticed, had powdered hair that curled all over their heads. She felt very curious to know what it was all about, and crept a little way out of the wood to listen.</p>
<p>The Fish-Footman began by producing from under his arm a great letter, nearly as large as himself, and this he handed over to the other, saying, in a solemn tone, “For the Duchess. An invitation from the Queen to play croquet.” The Frog-Footman repeated, in the same solemn tone, only changing the order of the words a little, “From the Queen. An invitation for the Duchess to play croquet.” Then they both bowed low, and their curls got entangled together.</p>$q$, '2026-07-23 09:00:00+00') on conflict (slug) do nothing;
insert into public.posts (slug,title,category,excerpt,body,published_at) values ($q$things-i-love-about-getting-older$q$, $q$3 of the things I love most about getting older$q$, $q$LIFESTYLE · TRENDING$q$, $q$I began walking, therefore, in a big curve, seeking some point of vantage and continually looking at the sand.$q$, $q$<p>After the glimpse I had had of the Martians emerging from the cylinder in which they had come to the earth from their planet, a kind of fascination paralysed my actions. I remained standing knee-deep in the heather, staring at the mound that hid them. I was a battleground of fear and curiosity.</p>
<p>I did not dare to go back towards the pit, but I felt a passionate longing to peer into it. I began walking, therefore, in a big curve, seeking some point of vantage and continually looking at the sand heaps that hid these new-comers to our earth.</p>
<p>Once a leash of thin black whips, like the arms of an octopus, flashed across the sunset and was immediately withdrawn, and afterwards a thin rod rose up, joint by joint, bearing at its apex a circular disk that spun with a wobbling motion. What could be going on there?</p>
<p>“We can’t possibly stay here,” I said; and as I spoke the firing reopened for a moment upon the common. “But where are we to go?” said my wife in terror. I thought, perplexed. Then I remembered her cousins at Leatherhead. “Leatherhead!” I shouted above the sudden noise. She looked away from me downhill. The people were coming out of their houses, astonished. “How are we to get to Leatherhead?” she said.</p>
<p>I started off at once for the Spotted Dog, for I knew the landlord had a horse and dog cart. I ran, for I perceived that in a moment everyone upon this side of the hill would be moving. I found him in his bar, quite unaware of what was going on behind his house. A man stood with his back to me, talking to him.</p>
<p>Down the hill I saw a bevy of hussars ride under the railway bridge; three galloped through the open gates of the Oriental College; two others dismounted, and began running from house to house. The sun, shining through the smoke that drove up from the tops of the trees, seemed blood red, and threw an unfamiliar, lurid light upon everything.</p>
<p>I and my wife stood amazed. Then I realised that the crest of Maybury Hill must be within range now that the college was cleared out of the way. At that I gripped my wife’s arm, and without ceremony ran her out into the road. Then I fetched out the servant, telling her I would go upstairs myself for the box she was clamouring for.</p>$q$, '2026-07-22 09:00:00+00') on conflict (slug) do nothing;
insert into public.posts (slug,title,category,excerpt,body,published_at) values ($q$everything-seems-possible-with-ai$q$, $q$Everything seems possible with AI$q$, $q$ECONOMICS · FEATURED$q$, $q$A moderate incline runs towards the foot of Maybury Hill, and down this we clattered.$q$, $q$<p>“What can I do for you?” she inquired softly, for she was moved by the sad voice in which the man spoke. “Get an oil-can and oil my joints,” he answered. “They are rusted so badly that I cannot move them at all; if I am well oiled I shall soon be all right again. You will find an oil-can on a shelf in my cottage.” Dorothy at once ran back to the cottage and found the oil-can, and then she returned and asked anxiously, “Where are your joints?”</p>
